<script lang="ts">
  import { onMount } from 'svelte'; import { goto } from '$app/navigation';
  import { TeacherApi, readableError, type ClassRoom, type FileTask, type FileTaskView } from '$lib/teacher-api'; import TeacherNav from '$lib/teacher/TeacherNav.svelte'; import '$lib/teacher/teacher.css';
  const api = new TeacherApi(); let ready = false; let busy = false; let error = ''; let notice = '';
  let classes: readonly ClassRoom[] = []; let selectedClassId = ''; let tasks: readonly FileTask[] = []; let taskId = ''; let view: FileTaskView | undefined;
  let title = ''; let description = ''; let deadline = ''; let preview: { url: string; name: string } | undefined;
  onMount(() => { void initialise(); });
  async function initialise(): Promise<void> { if (!await api.restoreTeacher()) { await goto('/'); return; } ready = true; await refresh(); }
  async function work(action: () => Promise<void>): Promise<void> { busy = true; error = ''; notice = ''; try { await action(); } catch (cause) { error = readableError(cause); } finally { busy = false; } }
  async function refresh(): Promise<void> { const page = await api.classes(); classes = page.items; if (!classes.some((entry) => entry.id === selectedClassId)) selectedClassId = classes[0]?.id ?? ''; tasks = selectedClassId ? (await api.fileTasks(selectedClassId)).items : []; if (!tasks.some((item) => item.id === taskId)) { taskId = tasks[0]?.id ?? ''; view = undefined; } if (taskId) await read(); }
  function toLocal(value: string): string { const date = new Date(value); return new Date(date.getTime() - date.getTimezoneOffset() * 60_000).toISOString().slice(0, 16); }
  function draft(): { title: string; description: string; deadlineAtUtc: string } { return { title, description, deadlineAtUtc: new Date(deadline).toISOString() }; }
  async function read(): Promise<void> { if (!selectedClassId || !taskId) return; view = await api.fileTask(selectedClassId, taskId); title = view.task.title; description = view.task.description; deadline = toLocal(view.task.deadlineAtUtc); preview = undefined; }
  async function create(): Promise<void> { if (!selectedClassId) { error = '請先建立或選擇班級。'; return; } await work(async () => { const task = await api.createFileTask(selectedClassId, draft()); taskId = task.id; await refresh(); notice = '已建立作業草稿。'; }); }
  async function update(): Promise<void> { if (!selectedClassId || !taskId) return; await work(async () => { await api.updateFileTask(selectedClassId, taskId, draft()); await read(); notice = '草稿已更新。'; }); }
  async function open(): Promise<void> { if (!selectedClassId || !taskId) return; await work(async () => { await api.openFileTask(selectedClassId, taskId); await read(); await refresh(); notice = '作業已開放。'; }); }
  async function close(): Promise<void> { if (!selectedClassId || !taskId) return; await work(async () => { await api.closeFileTask(selectedClassId, taskId); await read(); await refresh(); notice = '作業已關閉，可檢視交件及下載。'; }); }
  function safePreview(mime: string | null): boolean { return mime === 'application/pdf' || mime === 'image/png' || mime === 'image/jpeg' || mime === 'image/gif' || mime === 'image/webp' || mime === 'text/plain'; }
  async function logout(): Promise<void> { await api.logout(); await goto('/'); }
</script>
<main aria-busy={!ready}><TeacherNav current="assignments" onLogout={logout}/>
{#if !ready}<p>正在確認教師登入狀態…</p>{:else}<h2>收功課儀表板</h2><div aria-live="polite">{#if notice}<p class="notice">{notice}</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}</div>
<div class="grid two"><section class="panel"><h3>建立或編輯作業</h3><label for="assignment-class">班級</label><select id="assignment-class" bind:value={selectedClassId} on:change={() => void work(refresh)}>{#each classes as room}<option value={room.id}>{room.name}</option>{/each}</select><label for="title">標題</label><input id="title" bind:value={title} maxlength="200"/><label for="description">說明</label><textarea id="description" bind:value={description}></textarea><label for="deadline">截止時間</label><input id="deadline" type="datetime-local" bind:value={deadline}/><div class="actions"><button class="primary" on:click={() => void create()} disabled={busy}>建立草稿</button><button on:click={() => void update()} disabled={busy || !taskId}>更新草稿</button></div></section>
<section class="panel"><h3>作業清單與狀態</h3><label for="task">選擇作業</label><select id="task" bind:value={taskId} on:change={() => void work(read)}>{#each tasks as task}<option value={task.id}>{task.state}｜{task.title}</option>{/each}</select><div class="actions"><button on:click={() => void work(read)} disabled={busy || !taskId}>刷新儀表板</button><button class="primary" on:click={() => void open()} disabled={busy || !taskId}>開放</button><button on:click={() => void close()} disabled={busy || !taskId}>關閉收件</button></div>{#if view?.completion}<h4>繳交進度</h4><p class="notice">已交 {view.completion.submittedStudentCount} / {view.completion.eligibleStudentCount}</p><progress value={view.completion.submittedStudentCount} max={Math.max(1, view.completion.eligibleStudentCount)} aria-label="繳交進度"></progress><p class="muted">開放期間會透過即時事件更新；也可按「刷新儀表板」取得最新數字。</p>{/if}</section></div>
{#if view}<section class="panel"><h3>{view.task.title}：交件清單</h3>{#if view.task.state !== 'closed'}<p class="muted">關閉收件後顯示具名檔案清單；開放時為保護學生隱私，只顯示進度。</p>{:else if !view.submissions || view.submissions.length === 0}<p class="muted">尚未收到交件。</p>{:else}<div class="table-wrap"><table><thead><tr><th>學號</th><th>姓名</th><th>檔案</th><th>大小</th><th>交件時間</th><th>操作</th></tr></thead><tbody>{#each view.submissions as submission}<tr><td>{submission.studentNumber}</td><td>{submission.displayName}</td><td>{submission.displayFilename}</td><td>{submission.byteLength.toLocaleString()} bytes</td><td>{new Date(submission.receivedCompleteAtUtc).toLocaleString()}</td><td><div class="actions">{#if safePreview(submission.declaredMimeType)}<button class="small" on:click={() => preview = { url: api.previewUrl(selectedClassId, taskId, submission.studentId), name: submission.displayFilename }}>預覽</button>{/if}<a class="button small" href={api.downloadUrl(selectedClassId, taskId, submission.studentId)}>下載</a></div></td></tr>{/each}</tbody></table></div>{/if}</section>{/if}
{#if preview}<section class="panel" aria-label="檔案預覽"><div class="actions"><h3>{preview.name}</h3><button on:click={() => preview = undefined}>關閉預覽</button><a class="button" href={preview.url} target="_blank" rel="noopener">在新分頁開啟</a></div><iframe title={`預覽：${preview.name}`} src={preview.url} sandbox="allow-same-origin" style="width:100%;min-height:560px;border:1px solid #c8d3e3"></iframe><p class="muted">只會內嵌預覽 PDF、圖片與純文字；其他格式仍可安全下載。</p></section>{/if}{/if}</main>
